const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const {PGlite}=require('@electric-sql/pglite');
const R=path.resolve(__dirname,'..'),read=p=>fs.readFileSync(path.join(R,p),'utf8');
const A='总打码倍数1.3720(有效投注137.2/总充值100)小于配置4',B='累计提款次数0小于配置1次',C='首存金额5000大于等于配置4999';
async function setup(){const db=new PGlite();await db.exec('create schema private;');await db.exec(read('baseline/dashboard_admin_live_blocking_details_cleaned.sql').replace('private.dashboard_admin_live_blocking_details_cleaned(p_note text)','private.legacy_details(p_note text)'));for(const n of ['dashboard_admin_live_blocking_core','dashboard_admin_live_blocking_details_cleaned','dashboard_admin_live_blocking_members'])await db.exec(read('sql/'+n+'.sql'));return db;}
const cases=[A,B,C,`1.${A};2.${B}`,`1.${B};2.${A};3.${A}`,`${A};unknown;warning 42`,'unknown;other,code=502','用户充提差额不满足自动提现要求:-10000;Insufficient balance;Olá,solicite novamente','首存金额小于100，首存金额:50','打码倍数1.5小于3,充提差负盈利金额100大于等于50,按充提差负盈利放行','棋牌有效投注:12345>阈值:200','Insufficient balance','会员备注不为空,请检查备注','',null];
test('single core preserves exact legacy four-field JSON',async()=>{const db=await setup();try{for(const note of cases){const r=(await db.query('select private.legacy_details($1) old,private.dashboard_admin_live_blocking_details_cleaned($1) new',[note])).rows[0];assert.deepEqual(r.new,r.old,String(note));}}finally{await db.close();}});
test('proven membership across combinations, duplicates and ambiguous measurements',async()=>{const db=await setup();try{const get=async n=>(await db.query("select private.dashboard_admin_live_blocking_members(private.dashboard_admin_live_blocking_core($1),'newar','present')v",[n])).rows[0].v;let m=await get(`${A};${B};${A}`);assert.equal(m.length,2);assert.equal(m.find(x=>x.reason.startsWith('总打码')).details.actualValue,'1.3720');assert.equal((await get(`${A};${A.replace('1.3720','2.4700')}`))[0].details.actualValue,null);assert.equal((await get('unknown;other,code=502')).length,1);assert.deepEqual((await get(`${A};unknown;warning 42`)).map(x=>x.reason).sort(),[`${A};unknown;warning 42`,'总打码倍数小于配置倍数'].sort());assert.equal((await get(cases[9])).length,1);m=await get(cases[7]);assert(m.some(x=>x.reason==='代付余额不足'));assert(m.some(x=>x.reason==='充提差额未达免审要求'));assert(m.some(x=>x.reason===cases[7]));}finally{await db.close();}});
module.exports={setup,A,B,C,R,read};
test('all 110 historical classifier observations retain exact legacy JSON',async()=>{const db=await setup();try{for(const {note,expected}of JSON.parse(read('tests/legacy-corpus.json'))){const r=(await db.query('select private.dashboard_admin_live_blocking_details_cleaned($1)v',[note])).rows[0].v;assert.deepEqual(r,expected,String(note));}}finally{await db.close();}});
